describe('Rgb.reset', () => {
  let rgb;

  beforeEach(() => {
    rgb = new Rgb(100, 150, 200);
  });

  test('should reset r, g, and b values to 255', () => {
    rgb.reset();
    expect(rgb.r).toBe(255);
    expect(rgb.g).toBe(255);
    expect(rgb.b).toBe(255);
  });

  test('should not throw any errors when called', () => {
    expect(() => rgb.reset()).not.toThrow();
  });

  test('should work correctly when called multiple times', () => {
    rgb.reset();
    expect(rgb.r).toBe(255);
    expect(rgb.g).toBe(255);
    expect(rgb.b).toBe(255);

    rgb.r = 100;
    rgb.g = 50;
    rgb.b = 75;

    rgb.reset();
    expect(rgb.r).toBe(255);
    expect(rgb.g).toBe(255);
    expect(rgb.b).toBe(255);
  });
});

