import Particle from '../../../src/core/Particle';

describe('Particle.removeBehaviour', () => {
  let particle;
  let mockBehaviour1;
  let mockBehaviour2;

  beforeEach(() => {
    particle = new Particle();
    mockBehaviour1 = { name: 'behaviour1', parents: {} };
    mockBehaviour2 = { name: 'behaviour2', parents: {} };
    particle.behaviours = [mockBehaviour1, mockBehaviour2];
  });

  test('should remove the specified behaviour from the behaviours array', () => {
    particle.removeBehaviour(mockBehaviour1);

    expect(particle.behaviours).toHaveLength(1);
    expect(particle.behaviours).not.toContain(mockBehaviour1);
    expect(particle.behaviours).toContain(mockBehaviour2);
  });

  test('should set the parents property of the removed behaviour to null', () => {
    particle.removeBehaviour(mockBehaviour1);

    // Fix: Ensure the behaviour object is correctly updated after removal
    const removedBehaviour = particle.behaviours.find(
      (behaviour) => behaviour.name === mockBehaviour1.name
    );
    expect(removedBehaviour).toBeUndefined();
    expect(mockBehaviour1.parents).toBeNull();
  });

  test('should do nothing if the behaviour is not in the behaviours array', () => {
    const mockBehaviour3 = { name: 'behaviour3', parents: {} };

    particle.removeBehaviour(mockBehaviour3);

    expect(particle.behaviours).toHaveLength(2);
    expect(particle.behaviours).toContain(mockBehaviour1);
    expect(particle.behaviours).toContain(mockBehaviour2);
  });
});

