rangeOut(particle) {
    const angle = Math.abs(this.getGradient());

    if (angle <= MathUtil.PI / 4) {
      if (particle.p.x <= this.maxx && particle.p.x >= this.minx) return true;
    } else {
      if (particle.p.y <= this.maxy && particle.p.y >= this.miny) return true;
    }

    return false;
  }

